#pragma once
#include <cstdint>
#include <unordered_map>
#include <map>
#include <optional>

// Baseline limit-order-book engine keyed by price level using std::map
// (ordered, O(log n) per op).  This is the intentional 'before' baseline —
// the cache-unfriendly reference we will compare against a flat-array variant.
//
// Price levels are stored in fixed-point units (ITCH price * 10000, i.e. the
// raw uint32_t from the wire).  The public interface uses those raw units; the
// caller divides by 10000.0 for display.

namespace itch {

struct PriceLevel {
    uint32_t price_raw;   // fixed-point (divide by 10000 for real price)
    uint32_t shares;
};

struct TopOfBook {
    std::optional<PriceLevel> best_bid;
    std::optional<PriceLevel> best_ask;
};

// Per-order record: maps order_ref → (side, price, shares).
struct OrderRecord {
    char     side;
    uint32_t price_raw;
    uint32_t shares;
};

class OrderBook {
public:
    // Apply an Add-Order message.
    void add(uint64_t order_ref, char side, uint32_t price_raw, uint32_t shares);

    // Apply an Execute-Order message (partial or full fill).
    // Returns the executed shares actually removed (0 if order_ref unknown).
    uint32_t execute(uint64_t order_ref, uint32_t executed_shares);

    // Apply a Delete-Order message.
    // Returns true if the order was found and removed.
    bool del(uint64_t order_ref);

    // Apply a Replace-Order message.
    void replace(uint64_t old_ref, uint64_t new_ref, uint32_t shares, uint32_t price_raw);

    // Best bid (highest price) and best ask (lowest price).
    TopOfBook top_of_book() const;

    // Diagnostics.
    uint64_t error_count() const { return error_count_; }
    std::size_t order_count() const { return orders_.size(); }

private:
    // orders_[ref] → OrderRecord (side, price, shares)
    std::unordered_map<uint64_t, OrderRecord> orders_;

    // bids_[price] = total shares at that price level (highest = best bid)
    std::map<uint32_t, uint32_t, std::greater<uint32_t>> bids_;
    // asks_[price] = total shares at that price level (lowest = best ask)
    std::map<uint32_t, uint32_t> asks_;

    uint64_t error_count_ = 0;

    void _remove_shares(char side, uint32_t price_raw, uint32_t shares);
};

}  // namespace itch
